  S.Rooms = S.Rooms.filter((r) => r.room_number).map((r) => ({ ...r, hk_status: HK_STATUS.includes(r.hk_status) ? r.hk_status : 'Clean' }));
  S.cfg = {};
  for (const r of S.Config) if (r.key) S.cfg[String(r.key).trim()] = r.value ?? '';
  return S;
}

const overlaps = (aIn, aOut, bIn, bOut) => aIn < bOut && bIn < aOut;   // คืนที่ทับกัน (วันเช็กเอาต์ไม่นับ)

// ห้องว่างแต่ละประเภทในช่วงวัน (ไม่นับห้อง Out of Order และหักการจองที่ยังไม่ได้ระบุเลขห้อง)
function availability(S, ci, co, exceptId = '') {
  const busy = S.Bookings.filter((b) => ACTIVE.includes(b.status) && b.booking_id !== exceptId
    && b.check_in && b.check_out && overlaps(ci, co, b.check_in, b.check_out));
  const busyRooms = new Set(busy.filter((b) => b.room_number).map((b) => String(b.room_number)));
  const out = {};
  for (const t of S.RoomTypes) {
    const units = S.Rooms.filter((r) => r.room_type === t.room_type && r.hk_status !== 'Out of Order');
    const free = units.filter((r) => !busyRooms.has(String(r.room_number)));
    const unassigned = busy.filter((b) => !b.room_number && b.room_type === t.room_type).length;
    out[t.room_type] = { total: units.length, free, available: Math.max(0, free.length - unassigned) };
  }
  return out;
}
// เลือกห้อง: ห้องว่างที่สะอาดก่อน → ห้องว่างที่รอทำความสะอาด → ห้องที่แขกเดิมจะเช็กเอาต์วันนี้
// ขอ "ชั้นสูง" → ชั้นสูงก่อน, ที่เหลือเรียงเลขห้อง
function pickRoom(free, requests = '', S = null) {
  const high = /ชั้นสูง/.test(requests);
  const occupied = new Set((S ? S.Bookings : []).filter((x) => ['Checked-in', 'Need Attention'].includes(x.status) && x.room_number)
    .map((x) => String(x.room_number)));
  const rank = (r) => (occupied.has(String(r.room_number)) ? 2 : r.hk_status === 'Clean' ? 0 : 1);
  return [...free].sort((a, b) => (rank(a) - rank(b))
    || (high ? num(b.floor) - num(a.floor) : 0)
    || String(a.room_number).localeCompare(String(b.room_number), 'en', { numeric: true }))[0];
}

// ราคาต่อคืน (คืนวันศุกร์-เสาร์ใช้ weekend_price ถ้ามี)
function quote(type, ci, co) {
  const nights = [];
  let d = DateTime.fromISO(ci, { zone: ZONE });
  const end = DateTime.fromISO(co, { zone: ZONE });
  while (d.isValid && end.isValid && d < end && nights.length < 60) {
    const weekend = d.weekday === 5 || d.weekday === 6;
    const price = weekend && num(type.weekend_price) > 0 ? num(type.weekend_price) : num(type.price);
    nights.push({ date: d.toFormat('yyyy-MM-dd'), price, weekend });
    d = d.plus({ days: 1 });
  }
  return { nights, subtotal: nights.reduce((s, n) => s + n.price, 0) };
}

// โค้ดส่วนลด: ดีลส่วนตัวจากชีต Offers (Workflow E) หรือโค้ดทั่วไปจากชีต Promos
function checkPromo(S, code, uid) {
  code = String(code ?? '').trim().toUpperCase();
  if (!code) return null;
  const o = S.Offers.find((x) => String(x.promo_code).toUpperCase() === code);
  if (o) {
    if (o.converted_booking_id) return { code, valid: false, message: 'โค้ดนี้ถูกใช้ไปแล้ว' };
    if (o.valid_until && normDate(o.valid_until) < TODAY) return { code, valid: false, message: 'โค้ดนี้หมดอายุแล้ว' };
    if (uid && o.line_user_id && o.line_user_id !== uid) return { code, valid: false, message: 'โค้ดนี้เป็นสิทธิ์เฉพาะบัญชี LINE ที่ได้รับดีล' };
    const pct = num(o.discount, 10);
    return { code, valid: true, percent: pct, kind: 'personal', label: `ดีลพิเศษสำหรับคุณ ลด ${pct}%` };
  }
  const p = S.Promos.find((x) => String(x.code).toUpperCase() === code);
  if (p) {
    if (!bool(p.active, true)) return { code, valid: false, message: 'โค้ดนี้ปิดใช้งานแล้ว' };
    if (p.valid_until && normDate(p.valid_until) < TODAY) return { code, valid: false, message: 'โค้ดนี้หมดอายุแล้ว' };
    const pct = num(p.discount_percent);
    return { code, valid: pct > 0, percent: pct, kind: 'general', label: p.note || `ส่วนลด ${pct}%`, message: pct > 0 ? '' : 'โค้ดนี้ไม่มีส่วนลด' };
  }
  return { code, valid: false, message: 'ไม่พบโค้ดส่วนลดนี้' };
}
const discountOf = (subtotal, promo) => (promo && promo.valid ? Math.round(subtotal * Math.min(100, Math.max(0, promo.percent)) / 100) : 0);
const freeCancelUntil = (S, ci) => DateTime.fromISO(ci, { zone: ZONE }).minus({ days: num(S.cfg.free_cancel_days, 1) }).toFormat('yyyy-MM-dd');
const thaiDate = (ymd, weekday = true) => {
  const d = DateTime.fromISO(String(ymd || ''), { zone: ZONE });
  return d.isValid ? d.setLocale('th-TH').toLocaleString(weekday ? { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' } : { day: 'numeric', month: 'short', year: 'numeric' }) : String(ymd || '-');
};
const baht = (n) => '฿' + Math.round(num(n)).toLocaleString('en-US');
const guestsText = (b) => `${num(b.adults, 1)} ผู้ใหญ่${num(b.children) ? ` · ${num(b.children)} เด็ก` : ''}`;
const roomTypeName = (S, rt) => (S.RoomTypes.find((t) => t.room_type === rt) || {}).name || rt;
const hotelName = (S) => S.cfg.hotel_name || 'Sai Lan Hotel';

// ---- Flex แจ้งกลุ่มแม่บ้าน ----
function kv(label, value, strong = true) {
  return { type: 'box', layout: 'baseline', spacing: 'sm', contents: [
    { type: 'text', text: label, size: 'sm', color: '#8A8578', flex: 3 },
    { type: 'text', text: String(value || '-'), size: 'sm', color: '#1F1F25', weight: strong ? 'bold' : 'regular', flex: 7, wrap: true },
  ] };
}
function hkFlex(S, kind, b, extra = {}) {
  const TITLES = {
    new: ['📋 การจองใหม่ · เตรียมห้อง', '#8A6A1F'],
    checkout: ['🧹 เช็กเอาต์แล้ว · ทำความสะอาด', '#B23A2E'],
    move: ['🔁 แขกย้ายห้อง · ห้องเดิมว่างแล้ว', '#B23A2E'],
    reassign: ['🔁 เปลี่ยนห้อง · เตรียมห้องใหม่', '#8A6A1F'],
    cancel: ['❌ ยกเลิกการจอง · ไม่ต้องเตรียมห้อง', '#5C5850'],
  };
  const prep = kind === 'new' || kind === 'reassign';
  const [title, color] = TITLES[kind] || TITLES.new;
  const room = String(extra.room || b.room_number || '');
  const rows = [kv('ห้อง', `${room || 'ยังไม่ระบุ'} · ${roomTypeName(S, b.room_type)}`)];
  if (kind === 'reassign' && extra.from) rows.push(kv('ห้องเดิม', `${extra.from} (ไม่ต้องเตรียมแล้ว)`, false));
  if (prep || kind === 'cancel') {
    rows.push(kv('เช็กอิน', `${thaiDate(b.check_in)} · ${S.cfg.checkin_time || '14:00'}`));
    rows.push(kv('เช็กเอาต์', thaiDate(b.check_out)));
  }
  if (prep) {
    rows.push(kv('ผู้เข้าพัก', guestsText(b)));
    if (b.arrival_time) rows.push(kv('เวลาถึง', b.arrival_time));
    if (b.special_requests) rows.push(kv('คำขอพิเศษ', b.special_requests));
    if (b.check_in === TODAY) rows.push({ type: 'text', text: '⚡ เข้าพักวันนี้ กรุณาเตรียมห้องด่วน', size: 'sm', color: '#B23A2E', weight: 'bold', wrap: true, margin: 'md' });
  }
  if (kind === 'checkout' || kind === 'move') {
    rows.push(kv('เวลา', `${NOW.toFormat('HH:mm')} น.`));
    rows.push(kv('แขกถัดไป', extra.next || 'ยังไม่มีการจอง', !!extra.next));
  }
  const buttons = [];
  if (room && kind !== 'cancel') {
    if (!prep) buttons.push({ type: 'button', style: 'secondary', height: 'sm',
      action: { type: 'postback', label: 'เริ่มทำความสะอาด', data: `action=hk_start&room=${encodeURIComponent(room)}`, displayText: `🧹 เริ่มทำความสะอาดห้อง ${room}` } });
    buttons.push({ type: 'button', style: 'primary', color: '#2E7D4F', height: 'sm',
      action: { type: 'postback', label: 'ห้องพร้อมแล้ว ✅', data: `action=hk_done&room=${encodeURIComponent(room)}`, displayText: `✅ ห้อง ${room} พร้อมแล้ว` } });
  }
  const bubble = {
    type: 'bubble', size: 'kilo',
    header: { type: 'box', layout: 'vertical', backgroundColor: color, paddingAll: '14px',
      contents: [{ type: 'text', text: title, color: '#FFFFFF', weight: 'bold', size: 'md', wrap: true }] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '14px', contents: rows },
  };
  if (buttons.length) bubble.footer = { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '12px', contents: buttons };
  return { type: 'flex', altText: `${title} ห้อง ${room || '-'}`, contents: bubble };
}
// แขกคนถัดไปของห้องนี้ (วันนี้หรือหลังจากนี้)
function nextArrival(S, room, exceptId = '') {
  const n = S.Bookings.filter((x) => String(x.room_number) === String(room) && x.booking_id !== exceptId
    && x.status === 'Confirmed' && x.check_in >= TODAY).sort((a, c) => a.check_in.localeCompare(c.check_in))[0];
  if (!n) return '';
  return n.check_in === TODAY ? `⚠️ วันนี้ ${S.cfg.checkin_time || '14:00'} (${n.booking_id})` : `${thaiDate(n.check_in)} (${n.booking_id})`;
}
// ===== จบ helpers =====

// ===== Apply Action (Staff API · POST) — ตรวจสิทธิ์แล้วที่ Webhook (Header Auth) =====
// ผลลัพธ์ 1 item: { response, http_status, booking_update, booking_append, room_updates[], config_updates[], activity, pushes[] }
const body = $('Staff API').first().json.body || {};
const S = readSheets($input.first().json);
const cfg = S.cfg;
const BOOKING_COLS = ["booking_id", "created_at", "full_name", "phone", "email", "line_user_id", "check_in", "check_out", "room_type", "room_number", "status", "rating", "issue_category", "preference_tags", "rating_sent_at", "last_updated", "adults", "children", "arrival_time", "special_requests", "nights", "price_total", "discount", "promo_code", "payment_status", "source", "checked_in_at", "checked_out_at", "cancelled_at", "staff_note"];
const MUTABLE = ["full_name", "phone", "email", "check_in", "check_out", "room_type", "room_number", "status", "adults", "children", "arrival_time", "special_requests", "nights", "price_total", "discount", "payment_status", "checked_in_at", "checked_out_at", "cancelled_at", "staff_note", "last_updated"];
const NUMERIC = ["adults", "children", "nights", "price_total", "discount"];
const SOURCES = ['Walk-in', 'Phone', 'Agoda', 'Booking.com', 'Trip.com', 'Expedia', 'Other'];
const SETTINGS = ['hk_notify_new_booking', 'hk_notify_checkout', 'hk_daily_digest', 'pre_arrival_enabled'];
const staff = clip(body.staff, 40) || 'พนักงาน';
const action = String(body.action || '');
const force = body.force === true;

const out = { response: null, http_status: 200, booking_update: null, booking_append: null, room_updates: [], config_updates: [], activity: null, pushes: [] };
const done = () => [{ json: out, pairedItem: { item: 0 } }];
const fail = (code, message, extra = {}) => {
  Object.assign(out, { http_status: code, response: { success: false, message, ...extra }, booking_update: null, booking_append: null,
    room_updates: [], config_updates: [], activity: null, pushes: [] });
  return done();
};
const ok = (message, extra = {}) => { out.response = { success: true, message, ...extra }; return done(); };

const isYmd = (x) => /^\d{4}-\d{2}-\d{2}$/.test(x) && DateTime.fromISO(x).isValid;
const cell = (k, v) => (NUMERIC.includes(k) && String(v ?? '').trim() !== '' && Number.isFinite(num(v, NaN)) ? num(v) : String(v ?? ''));
const findB = (id) => S.Bookings.find((b) => b.booking_id === String(id || '').trim());
const findRoom = (n) => S.Rooms.find((r) => String(r.room_number) === String(n ?? '').trim());
const nightsOf = (ci, co) => Math.round(DateTime.fromISO(co, { zone: ZONE }).diff(DateTime.fromISO(ci, { zone: ZONE }), 'days').days);
const hkGroup = (key) => (cfg.housekeeping_group_id && bool(cfg[key], true) ? cfg.housekeeping_group_id : '');
const pushHK = (key, msg) => { const g = hkGroup(key); if (g) out.pushes.push({ to: g, messages: [msg] }); return !!g; };
const log = (act, b, room, detail) => { out.activity = { timestamp: TS, staff, action: act, booking_id: b ? b.booking_id : '',
  room_number: String(room || (b && b.room_number) || ''), detail: clip(detail, 300) }; };
const setRoom = (room, st, note) => out.room_updates.push({ room_number: String(room.room_number), hk_status: st,
  hk_note: note !== undefined ? clip(note, 200) : (st === 'Clean' ? '' : room.hk_note || ''), hk_updated_at: TS, hk_updated_by: staff });
const save = (b, changes) => { const nb = { ...b, ...changes, last_updated: TS };
  out.booking_update = Object.fromEntries(['booking_id', ...MUTABLE].map((k) => [k, cell(k, nb[k])])); return nb; };
const addNote = (b, t) => clip([b.staff_note, `${NOW.toFormat('dd/MM HH:mm')} ${staff}: ${t}`].filter(Boolean).join(' | '), 1000);
const inHouseStatus = (s) => ['Checked-in', 'Need Attention'].includes(s);
// การจองอื่นที่ใช้ห้องนี้ทับช่วงวัน / แขกที่ยังพักอยู่ในห้องนี้
const roomConflict = (roomNo, ci, co, exceptId) => S.Bookings.find((x) => x.booking_id !== exceptId && ACTIVE.includes(x.status)
  && String(x.room_number) === String(roomNo) && overlaps(ci, co, x.check_in, x.check_out));
const occupant = (roomNo, exceptId) => S.Bookings.find((x) => x.booking_id !== exceptId && inHouseStatus(x.status) && String(x.room_number) === String(roomNo));
const roomReady = (room, exceptId) => {
  const occ = occupant(room.room_number, exceptId);
  if (occ) return `ห้อง ${room.room_number} ยังมีแขกพักอยู่ (${occ.booking_id} · ${occ.full_name}) ต้องเช็กเอาต์ก่อน`;
  return '';
};

const b = body.booking_id ? findB(body.booking_id) : null;
if (body.booking_id && !b) return fail(404, `ไม่พบการจอง ${body.booking_id}`);
const needB = ['check_in', 'check_out', 'cancel', 'no_show', 'resolve_issue', 'change_room', 'update_booking'];
if (needB.includes(action) && !b) return fail(400, 'ต้องระบุ booking_id');
const statusTh = (x) => STATUS_TH[x.status] || x.status;

switch (action) {
  // ---------------- เช็กอิน ----------------
  case 'check_in': {
    if (b.status !== 'Confirmed') return fail(409, `การจองนี้อยู่ในสถานะ "${statusTh(b)}" เช็กอินไม่ได้`);
    if (b.check_in > TODAY) return fail(409, `ยังไม่ถึงวันเช็กอิน (${thaiDate(b.check_in)}) ถ้าแขกมาก่อนกำหนด ให้แก้วันเข้าพักก่อน`);
    if (b.check_out <= TODAY) return fail(409, 'เลยวันเช็กเอาต์ของการจองนี้แล้ว ถ้าแขกจะพักต่อ ให้แก้วันเช็กเอาต์ก่อน');
    const roomNo = clip(body.room_number, 10) || b.room_number;
    if (!roomNo) return fail(400, 'กรุณาเลือกห้องก่อนเช็กอิน');
    const room = findRoom(roomNo);
    if (!room) return fail(404, `ไม่พบห้อง ${roomNo} ในชีต Rooms`);
    if (room.hk_status === 'Out of Order') return fail(409, `ห้อง ${roomNo} ปิดปรับปรุงอยู่`);
    const busy = roomReady(room, b.booking_id);
    if (busy) return fail(409, busy);
    const clash = roomConflict(roomNo, TODAY, b.check_out, b.booking_id);
    if (clash) return fail(409, `ห้อง ${roomNo} มีการจอง ${clash.booking_id} (${clash.full_name}) ทับช่วงวันนี้`);
    if (room.hk_status !== 'Clean' && !force)
      return fail(409, `ห้อง ${roomNo} สถานะ "${HK_TH[room.hk_status]}" ยังไม่พร้อม ยืนยันจะเช็กอินต่อหรือไม่?`, { need_force: true });
    const changes = { status: 'Checked-in', room_number: String(room.room_number), checked_in_at: TS };
    if (room.room_type !== b.room_type) changes.room_type = room.room_type;
    if (body.paid === true) changes.payment_status = 'Paid';
    save(b, changes);
    log('check_in', b, room.room_number, `เช็กอินห้อง ${room.room_number}`
      + (room.room_type !== b.room_type ? ` (เปลี่ยนจาก ${b.room_type})` : '')
      + (room.hk_status !== 'Clean' ? ` · ห้องสถานะ${HK_TH[room.hk_status]}` : '') + (body.paid === true ? ' · ชำระเงินแล้ว' : ''));
    return ok(`เช็กอินคุณ${b.full_name} เข้าห้อง ${room.room_number} แล้ว`);
  }

  // ---------------- เช็กเอาต์ → ห้องเป็น Dirty + แจ้งกลุ่มแม่บ้าน ----------------
  case 'check_out': {
    if (!inHouseStatus(b.status)) return fail(409, `การจองนี้อยู่ในสถานะ "${statusTh(b)}" เช็กเอาต์ไม่ได้`);
    const changes = { status: 'Checked-out', checked_out_at: TS };
    if (body.paid === true) changes.payment_status = 'Paid';
    const early = b.check_out > TODAY;
    save(b, changes);
    const room = findRoom(b.room_number);
    let told = false;
    if (room) {
      setRoom(room, 'Dirty', `เช็กเอาต์ ${NOW.toFormat('HH:mm')} น.`);
      told = pushHK('hk_notify_checkout', hkFlex(S, 'checkout', b, { next: nextArrival(S, room.room_number, b.booking_id) }));
    }
    log('check_out', b, b.room_number, `เช็กเอาต์${early ? 'ก่อนกำหนด' : ''}${body.paid === true ? ' · ชำระเงินแล้ว' : ''}${b.status === 'Need Attention' ? ' · มีปัญหาค้าง: ' + (b.issue_category || '-') : ''}`);
    return ok(`เช็กเอาต์ห้อง ${b.room_number || '-'} แล้ว${told ? ' · แจ้งกลุ่มแม่บ้านให้ทำความสะอาดแล้ว' : ''}`, { housekeeping_notified: told });
  }

  // ---------------- ยกเลิก / ไม่มาเข้าพัก ----------------
  case 'cancel': {
    if (b.status !== 'Confirmed') return fail(409, `ยกเลิกได้เฉพาะการจองที่ยังไม่เช็กอิน (ตอนนี้: ${statusTh(b)})`);
    const reason = clip(body.reason, 200);
    save(b, { status: 'Cancelled', cancelled_at: TS, staff_note: addNote(b, 'ยกเลิก' + (reason ? ': ' + reason : '')) });
    const told = b.room_number && b.check_in <= TOMORROW ? pushHK('hk_notify_new_booking', hkFlex(S, 'cancel', b)) : false;
    log('cancel', b, b.room_number, `ยกเลิกโดยพนักงาน${reason ? ': ' + reason : ''}`);
    return ok(`ยกเลิกการจอง ${b.booking_id} แล้ว${told ? ' · แจ้งกลุ่มแม่บ้านแล้ว' : ''}`);
  }
  case 'no_show': {
    if (b.status !== 'Confirmed') return fail(409, `การจองนี้อยู่ในสถานะ "${statusTh(b)}"`);
    if (b.check_in > TODAY) return fail(409, 'ยังไม่ถึงวันเช็กอิน จึงยังบันทึกว่าไม่มาเข้าพักไม่ได้');
    save(b, { status: 'No-show', staff_note: addNote(b, 'ไม่มาเข้าพัก') });
    log('no_show', b, b.room_number, 'บันทึกว่าไม่มาเข้าพัก');
    return ok(`บันทึก ${b.booking_id} เป็น "ไม่มาเข้าพัก" แล้ว ห้องว่างสำหรับขายต่อ`);
  }

  // ---------------- ปิดเรื่องที่แขกแจ้ง ----------------
  case 'resolve_issue': {
    if (b.status !== 'Need Attention') return fail(409, 'การจองนี้ไม่มีเรื่องค้างให้ปิด');
    const note = clip(body.note, 200);
    save(b, { status: 'Checked-in', staff_note: addNote(b, `แก้ไขเรื่อง "${b.issue_category || '-'}" แล้ว${note ? ': ' + note : ''}`) });
    const notify = body.notify_guest === true && /^U[0-9a-f]{32}$/.test(b.line_user_id);
    if (notify) out.pushes.push({ to: b.line_user_id, messages: [{ type: 'text',
      text: `เรื่อง "${b.issue_category || 'ที่แจ้งไว้'}" ได้รับการแก้ไขเรียบร้อยแล้วค่ะ 🙏${note ? '\n' + note : ''}\nหากยังมีอะไรไม่สะดวก พิมพ์บอกเราในแชทนี้ได้ตลอดเลยนะคะ` }] });
    log('resolve_issue', b, b.room_number, `ปิดเรื่อง "${b.issue_category || '-'}"${note ? ': ' + note : ''}${notify ? ' · แจ้งแขกทาง LINE' : ''}`);
    return ok(`ปิดเรื่องของห้อง ${b.room_number || '-'} แล้ว${notify ? ' · ส่งข้อความแจ้งแขกแล้ว' : ''}`);
  }

  // ---------------- ย้ายห้อง / เปลี่ยนห้องที่จัดไว้ ----------------
  case 'change_room': {
    if (!ACTIVE.includes(b.status)) return fail(409, `การจองนี้อยู่ในสถานะ "${statusTh(b)}" ย้ายห้องไม่ได้`);
    const room = findRoom(body.room_number);
    if (!room) return fail(404, `ไม่พบห้อง ${body.room_number || '(ว่าง)'} ในชีต Rooms`);
    if (String(room.room_number) === String(b.room_number)) return fail(400, 'เป็นห้องเดิมอยู่แล้ว');
    if (room.hk_status === 'Out of Order') return fail(409, `ห้อง ${room.room_number} ปิดปรับปรุงอยู่`);
    const inHouse = inHouseStatus(b.status);
    const from = inHouse && TODAY > b.check_in ? TODAY : b.check_in;
    const to = b.check_out > from ? b.check_out : DateTime.fromISO(from).plus({ days: 1 }).toFormat('yyyy-MM-dd');
    const clash = roomConflict(room.room_number, from, to, b.booking_id);
    if (clash) return fail(409, `ห้อง ${room.room_number} มีการจอง ${clash.booking_id} (${clash.full_name}) ทับช่วงวันนี้`);
    if (inHouse) {
      const busy = roomReady(room, b.booking_id);
      if (busy) return fail(409, busy);
      if (room.hk_status !== 'Clean' && !force)
        return fail(409, `ห้อง ${room.room_number} สถานะ "${HK_TH[room.hk_status]}" ยังไม่พร้อม ยืนยันจะย้ายต่อหรือไม่?`, { need_force: true });
    }
    const changes = { room_number: String(room.room_number) };
    if (room.room_type !== b.room_type) changes.room_type = room.room_type;
    const nb = save(b, changes);
    const old = findRoom(b.room_number);
    let told = false;
    if (inHouse && old) {
      setRoom(old, 'Dirty', `แขกย้ายไปห้อง ${room.room_number}`);
      told = pushHK('hk_notify_checkout', hkFlex(S, 'move', b, { room: old.room_number, next: nextArrival(S, old.room_number, b.booking_id) }));
    } else if (!inHouse && b.check_in <= TOMORROW) {
      told = pushHK('hk_notify_new_booking', hkFlex(S, 'reassign', nb, { from: b.room_number }));
    }
    log('change_room', b, room.room_number, `ย้ายจากห้อง ${b.room_number || '-'} ไปห้อง ${room.room_number}${changes.room_type ? ` (${changes.room_type})` : ''}`);
    return ok(`ย้ายไปห้อง ${room.room_number} แล้ว${told ? ' · แจ้งกลุ่มแม่บ้านแล้ว' : ''}`);
  }

  // ---------------- แก้ไขข้อมูลการจอง ----------------
  case 'update_booking': {
    const f = body.fields || {};
    const changes = {};
    const TXT = { full_name: 100, phone: 20, email: 120, arrival_time: 40, special_requests: 500, staff_note: 1000 };
    for (const [k, n] of Object.entries(TXT)) if (k in f) changes[k] = clip(f[k], n).replace(/[\r\n]+/g, ' ');
    if ('full_name' in changes && changes.full_name.length < 2) return fail(400, 'ชื่อผู้เข้าพักสั้นเกินไป');
    if (changes.email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(changes.email)) return fail(400, 'อีเมลไม่ถูกต้อง');
    for (const k of ['adults', 'children']) if (k in f) {
      const v = Math.floor(num(f[k], -1));
      if (v < (k === 'adults' ? 1 : 0) || v > 10) return fail(400, `จำนวน${k === 'adults' ? 'ผู้ใหญ่' : 'เด็ก'}ไม่ถูกต้อง`);
      changes[k] = v;
    }
    if ('payment_status' in f) {
      if (!['Unpaid', 'Deposit', 'Paid'].includes(f.payment_status)) return fail(400, 'สถานะการชำระเงินไม่ถูกต้อง');
      changes.payment_status = f.payment_status;
    }
    for (const k of ['price_total', 'discount']) if (k in f && String(f[k]).trim() !== '') {
      const v = num(f[k], -1);
      if (v < 0 || v > 10000000) return fail(400, 'จำนวนเงินไม่ถูกต้อง');
      changes[k] = Math.round(v);
    }
    const ci = 'check_in' in f ? normDate(f.check_in) : b.check_in;
    const co = 'check_out' in f ? normDate(f.check_out) : b.check_out;
    if (ci !== b.check_in || co !== b.check_out) {
      if (!ACTIVE.includes(b.status)) return fail(409, 'แก้วันที่ได้เฉพาะการจองที่ยังใช้งานอยู่');
      if (inHouseStatus(b.status) && ci !== b.check_in) return fail(409, 'แขกเช็กอินแล้ว แก้ได้เฉพาะวันเช็กเอาต์');
      if (!isYmd(ci) || !isYmd(co)) return fail(400, 'รูปแบบวันที่ไม่ถูกต้อง');
      const nights = nightsOf(ci, co);
      if (nights < 1 || nights > 60) return fail(400, 'จำนวนคืนต้องอยู่ระหว่าง 1–60 คืน');
      if (b.status === 'Confirmed' && ci < TODAY) return fail(400, 'วันเช็กอินผ่านไปแล้ว');
      if (inHouseStatus(b.status) && co <= TODAY) return fail(400, 'วันเช็กเอาต์ต้องเป็นหลังวันนี้ (ถ้าแขกออกวันนี้ ให้กดเช็กเอาต์)');
      if (b.room_number) {
        const clash = roomConflict(b.room_number, ci, co, b.booking_id);
        if (clash) return fail(409, `ห้อง ${b.room_number} ไม่ว่างในช่วงใหม่ (ชนกับ ${clash.booking_id}) ย้ายห้องก่อนแล้วค่อยแก้วัน`);
      } else if (((availability(S, ci, co, b.booking_id)[b.room_type] || {}).available || 0) <= 0) {
        return fail(409, `${roomTypeName(S, b.room_type)} ไม่มีห้องว่างในช่วงใหม่`);
      }
      Object.assign(changes, { check_in: ci, check_out: co, nights });
      const type = S.RoomTypes.find((t) => t.room_type === b.room_type);
      if (type && !('price_total' in changes)) {   // คิดราคาใหม่ตามวัน โดยคงสัดส่วนส่วนลดเดิม
        const sub = quote(type, ci, co).subtotal;
        const oldSub = num(b.price_total) + num(b.discount);
        const disc = Math.round(sub * (oldSub > 0 ? num(b.discount) / oldSub : 0));
        Object.assign(changes, { discount: disc, price_total: sub - disc });
      }
    }
    const type = S.RoomTypes.find((t) => t.room_type === b.room_type);
    const guests = (changes.adults ?? num(b.adults, 1)) + (changes.children ?? num(b.children, 0));
    if (type && guests > num(type.max_guests, 2)) return fail(400, `${type.name || b.room_type} รองรับได้สูงสุด ${num(type.max_guests, 2)} ท่าน`);
    const changed = Object.keys(changes).filter((k) => String(changes[k]) !== String(b[k] ?? ''));
    if (!changed.length) return fail(400, 'ไม่มีข้อมูลที่เปลี่ยนแปลง');
    save(b, changes);
    log('update_booking', b, b.room_number, 'แก้ไข ' + changed.join(', '));
    return ok('บันทึกการแก้ไขแล้ว', { changed, price_total: changes.price_total });
  }

  // ---------------- สถานะห้อง (แม่บ้าน) ----------------
  case 'set_room_status': {
    const room = findRoom(body.room_number);
    if (!room) return fail(404, `ไม่พบห้อง ${body.room_number || '(ว่าง)'}`);
    const st = String(body.hk_status || '');
    if (!HK_STATUS.includes(st)) return fail(400, 'สถานะห้องไม่ถูกต้อง');
    const note = 'note' in body ? clip(body.note, 200) : undefined;
    setRoom(room, st, note);
    log('room_status', null, room.room_number, `${HK_TH[room.hk_status]} → ${HK_TH[st]}${note ? ' · ' + note : ''}`);
    const affected = st === 'Out of Order' ? S.Bookings.filter((x) => ACTIVE.includes(x.status)
      && String(x.room_number) === String(room.room_number) && x.check_out > TODAY).map((x) => x.booking_id) : [];
    return ok(`ห้อง ${room.room_number}: ${HK_TH[st]}`, affected.length ? { warning: `ห้องนี้มีการจองอยู่ (${affected.join(', ')}) ควรย้ายห้องให้แขก` } : {});
  }

  // ---------------- เปิด/ปิดการแจ้งเตือน ----------------
  case 'set_config': {
    const vals = body.values || {};
    for (const k of SETTINGS) if (typeof vals[k] === 'boolean') out.config_updates.push({ key: k, value: vals[k] ? 'TRUE' : 'FALSE' });
    if (!out.config_updates.length) return fail(400, 'ไม่มีค่าที่ตั้งได้');
    log('settings', null, '', out.config_updates.map((c) => `${c.key}=${c.value}`).join(', '));
    return ok('บันทึกการตั้งค่าแล้ว');
  }

  // ---------------- บันทึกการจองจากช่องทางอื่น (Walk-in / โทร / OTA) ----------------
  case 'create_booking': {
    const f = body.booking || {};
    const full_name = clip(f.full_name, 100).replace(/\s+/g, ' ');
    const phone = clip(f.phone, 20);
    const email = clip(f.email, 120).toLowerCase();
    const source = SOURCES.includes(f.source) ? f.source : 'Walk-in';
    const ci = normDate(f.check_in), co = normDate(f.check_out);
    const adults = Math.floor(num(f.adults, 1)), children = Math.floor(num(f.children, 0));
    const special_requests = clip(f.special_requests, 500).replace(/[\r\n]+/g, ' ');
    const errors = [];
    if (full_name.length < 2) errors.push('ชื่อผู้เข้าพัก');
    if (phone && !/^\+?[\d\s-]{6,20}$/.test(phone)) errors.push('เบอร์โทร');
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.push('อีเมล');
    if (adults < 1 || adults > 10) errors.push('จำนวนผู้ใหญ่');
    if (children < 0 || children > 10) errors.push('จำนวนเด็ก');
    let nights = 0;
    if (!isYmd(ci) || !isYmd(co)) errors.push('วันที่เข้าพัก');
    else {
      nights = nightsOf(ci, co);
      if (ci < TODAY) errors.push('วันเช็กอินผ่านไปแล้ว');
      if (nights < 1 || nights > 60) errors.push('จำนวนคืน (1–60)');
    }
    let room = f.room_number ? findRoom(f.room_number) : null;
    if (f.room_number && !room) errors.push(`ห้อง ${f.room_number}`);
    const rt = room ? room.room_type : clip(f.room_type, 30);
    const type = S.RoomTypes.find((t) => t.room_type === rt);
    if (!type) errors.push('ประเภทห้อง');
    else if (adults + children > num(type.max_guests, 2)) errors.push(`${type.name || rt} รองรับสูงสุด ${num(type.max_guests, 2)} ท่าน`);
    if (errors.length) return fail(400, 'ข้อมูลไม่ถูกต้อง: ' + errors.join(', '));

    if (room) {
      if (room.hk_status === 'Out of Order') return fail(409, `ห้อง ${room.room_number} ปิดปรับปรุงอยู่`);
      const clash = roomConflict(room.room_number, ci, co, '');
      if (clash) return fail(409, `ห้อง ${room.room_number} มีการจอง ${clash.booking_id} (${clash.full_name}) ทับช่วงวันนี้`);
    }
    const av = availability(S, ci, co)[rt] || { available: 0, free: [] };
    if (av.available <= 0) return fail(409, `${type.name || rt} เต็มแล้วในวันที่เลือก`);
    if (!room) room = pickRoom(av.free, special_requests, S);

    const checkInNow = f.check_in_now === true;
    if (checkInNow) {
      if (ci !== TODAY) return fail(400, 'เช็กอินทันทีได้เฉพาะการจองที่เข้าพักวันนี้');
      if (!room) return fail(409, 'ไม่มีห้องว่างให้เช็กอิน');
      const busy = roomReady(room, '');
      if (busy) return fail(409, busy);
      if (room.hk_status !== 'Clean' && !force)
        return fail(409, `ห้อง ${room.room_number} สถานะ "${HK_TH[room.hk_status]}" ยังไม่พร้อม ยืนยันจะเช็กอินต่อหรือไม่?`, { need_force: true });
    }
    const priceGiven = String(f.price_total ?? '').trim() !== '';
    const price_total = priceGiven ? Math.round(num(f.price_total, -1)) : quote(type, ci, co).subtotal;
    if (price_total < 0 || price_total > 10000000) return fail(400, 'ราคาไม่ถูกต้อง');

    // booking_id = BK-YYYYMMDD-XXXX (ไม่ซ้ำ)
    const ALPHA = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    const ymd = NOW.toFormat('yyyyMMdd');
    const store = $getWorkflowStaticData('global');
    store.issued = store.issued || {};
    for (const d of Object.keys(store.issued)) if (d !== ymd) delete store.issued[d];
    const used = new Set([...(store.issued[ymd] || []), ...S.Bookings.map((x) => x.booking_id)]);
    let booking_id;
    do { booking_id = `BK-${ymd}-` + Array.from({ length: 4 }, () => ALPHA[Math.floor(Math.random() * ALPHA.length)]).join(''); } while (used.has(booking_id));
    store.issued[ymd] = [...(store.issued[ymd] || []), booking_id];

    const row = {
      booking_id, created_at: TS, full_name, phone, email, line_user_id: '', check_in: ci, check_out: co, room_type: rt,
      room_number: room ? String(room.room_number) : '', status: checkInNow ? 'Checked-in' : 'Confirmed', rating: '', issue_category: '',
      preference_tags: '', rating_sent_at: '', last_updated: TS, adults, children, arrival_time: clip(f.arrival_time, 40), special_requests,
      nights, price_total, discount: 0, promo_code: '', payment_status: f.paid === true ? 'Paid' : 'Unpaid', source,
      checked_in_at: checkInNow ? TS : '', checked_out_at: '', cancelled_at: '', staff_note: clip(f.staff_note, 1000).replace(/[\r\n]+/g, ' '),
    };
    out.booking_append = Object.fromEntries(BOOKING_COLS.map((k) => [k, cell(k, row[k])]));
    const told = !checkInNow && row.room_number ? pushHK('hk_notify_new_booking', hkFlex(S, 'new', row)) : false;
    log('create_booking', row, row.room_number, `${source} · ${type.name || rt} · ${nights} คืน · ${baht(price_total)}${checkInNow ? ' · เช็กอินทันที' : ''}`);
    return ok(`บันทึกการจอง ${booking_id} แล้ว${row.room_number ? ` · ห้อง ${row.room_number}` : ''}${told ? ' · แจ้งกลุ่มแม่บ้านแล้ว' : ''}`,
      { booking_id, room_number: row.room_number });
  }

  default:
    return fail(400, `ไม่รู้จักคำสั่ง "${action}"`);
}

// ===== Collect Result: รวมผล (บันทึกชีตสำเร็จไหม / LINE ส่งได้ไหม) แล้วตอบหน้าเว็บ =====
const a = $('Apply Action').first().json;
const failed = ['Update Booking', 'Append Booking', 'Update Room', 'Save Config']
  .filter((n) => $(n).isExecuted && $(n).all().some((i) => i.json.error));
const lineFailed = $('Send Push').isExecuted ? $('Send Push').all().filter((i) => i.json.statusCode !== 200).length : 0;
let response = { ...a.response };
let code = a.http_status;
if (failed.length && code < 400) {
  code = 502;
  response = { success: false, message: `บันทึกลง Google Sheets ไม่สำเร็จ (${failed.join(', ')}) กรุณากดรีเฟรชแล้วลองใหม่` };
}
if (lineFailed) response.line_warning = `ส่งข้อความ LINE ไม่สำเร็จ ${lineFailed} รายการ (อาจเกินโควตาข้อความฟรีของเดือนนี้)`;
return [{ json: { response, http_status: code }, pairedItem: { item: 0 } }];
